INSERT INTO invites (
    collection_id
,   invite_code
,   role
,   expires_at
,   created_by
) VALUES (
    #{collectionId}
,   #{inviteCode}
,   #{role}
,   #{expiresAt}
,   #{createdBy}
)

mapper.update:
UPDATE  invites
SET     active_yn = 'N'
WHERE   invite_id = #{inviteId}

mapper.insert:
INSERT IGNORE INTO pending_invites (
    invite_id
,   user_id
) VALUES (
    #{inviteId}
,   #{userId}
)

mapper.delete:
DELETE  pi
FROM    pending_invites pi
JOIN    invites i ON i.invite_id = pi.invite_id
WHERE   pi.user_id = #{userId}
AND     i.collection_id = #{collectionId}
